/* Research Pipeline: shared page selector. Data comes from assets/nav.js (window.RP_NAV, generated by the index builder).
   Without JS the brand still links home and a <noscript> "All pages" link remains. */
(function () {
  "use strict";
  var nav = document.querySelector(".rp-nav"), data = window.RP_NAV;
  if (!nav || !data || !data.sections) return;
  var btn = nav.querySelector(".rp-navbtn"), panel = nav.querySelector(".rp-navpanel");
  if (!btn || !panel) return;
  var root = new URL(nav.getAttribute("data-root") || "./", location.href);
  var norm = function (u) { return u.split("#")[0].split("?")[0].replace(/index\.html$/, ""); };
  var here = norm(location.href);
  var el = function (tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  var current = null;
  function link(item, latest) {
    var a = el("a", "rp-nitem" + (latest ? " is-latest" : "")), url = new URL(item.href, root).href;
    a.href = url;
    var t = el("span", "rp-nt", item.title);
    a.appendChild(t);
    if (item.date || latest) {
      var m = el("span", "rp-nm");
      if (latest) m.appendChild(el("span", "rp-nlatest", "Latest"));
      if (item.date) m.appendChild(document.createTextNode(item.date));
      a.appendChild(m);
    }
    if (norm(url) === here) { a.setAttribute("aria-current", "page"); current = current || a; }
    return a;
  }
  data.sections.forEach(function (sec) {
    var s = el("section", "rp-nsec"), hid = "rp-ns-" + sec.id, h = el("h2", "rp-nhead", sec.title);
    h.id = hid; s.setAttribute("aria-labelledby", hid); s.appendChild(h);
    if (!sec.items.length) { s.appendChild(el("p", "rp-nsoon", sec.note || "Coming soon")); panel.appendChild(s); return; }
    var ul = el("ul", "rp-nlist");
    sec.items.forEach(function (it, i) {
      if (i === 1 && sec.items[0].date) { var sub = el("li", "rp-nsub", "Earlier"); sub.setAttribute("aria-hidden", "true"); ul.appendChild(sub); }
      var li = el("li"); li.appendChild(link(it, i === 0 && !!it.date)); ul.appendChild(li);
    });
    s.appendChild(ul); panel.appendChild(s);
  });
  if (data.links && data.links.length) {
    var f = el("div", "rp-nfoot");
    data.links.forEach(function (l) { var a = el("a", "rp-nitem rp-nsmall", l.title); a.href = new URL(l.href, root).href; f.appendChild(a); });
    panel.appendChild(f);
  }
  var items = function () { return Array.prototype.slice.call(panel.querySelectorAll("a")); };
  var bar = document.querySelector(".rp-bar");
  function place() {
    var top = Math.round((bar ? bar.getBoundingClientRect().bottom : 56) + 6);
    panel.style.top = top + "px";
    var br = btn.getBoundingClientRect(); panel.style.right = (window.innerWidth < 520 ? 12 : Math.max(12, Math.round(window.innerWidth - br.right))) + "px";
    panel.style.maxHeight = Math.max(200, window.innerHeight - top - 12) + "px";
  }
  function open(focusFirst) {
    place(); panel.hidden = false; btn.setAttribute("aria-expanded", "true"); nav.classList.add("is-open");
    var target = focusFirst === "last" ? items()[items().length - 1] : (current || items()[0]);
    if (target) { target.focus({ preventScroll: true }); if (target.scrollIntoView) target.scrollIntoView({ block: "nearest" }); }
  }
  function close(returnFocus) {
    if (panel.hidden) return;
    panel.hidden = true; btn.setAttribute("aria-expanded", "false"); nav.classList.remove("is-open");
    if (returnFocus) btn.focus();
  }
  btn.addEventListener("click", function () { panel.hidden ? open() : close(true); });
  btn.addEventListener("keydown", function (e) {
    if (e.key === "ArrowDown") { e.preventDefault(); open(); }
    else if (e.key === "ArrowUp") { e.preventDefault(); open("last"); }
  });
  panel.addEventListener("keydown", function (e) {
    var list = items(), i = list.indexOf(document.activeElement);
    if (e.key === "Escape") { e.preventDefault(); close(true); }
    else if (e.key === "ArrowDown") { e.preventDefault(); (list[i + 1] || list[0]).focus(); }
    else if (e.key === "ArrowUp") { e.preventDefault(); (list[i - 1] || list[list.length - 1]).focus(); }
    else if (e.key === "Home") { e.preventDefault(); list[0].focus(); }
    else if (e.key === "End") { e.preventDefault(); list[list.length - 1].focus(); }
  });
  document.addEventListener("keydown", function (e) { if (e.key === "Escape" && !panel.hidden) close(true); });
  nav.addEventListener("focusout", function (e) { if (e.relatedTarget && !nav.contains(e.relatedTarget)) close(false); });
  document.addEventListener("pointerdown", function (e) { if (!panel.hidden && !nav.contains(e.target)) close(false); });
  window.addEventListener("resize", function () { if (!panel.hidden) place(); });
  btn.hidden = false;
})();
